// Editable sample resume. The sheet (#resume) is generated by scripts/build.js from
// content/resumes.js. Edits are saved in this browser; downloads are Word (.doc, opens in Word or
// Google Docs and can be saved as .docx), PDF (print dialog → Save as PDF, text stays selectable
// for ATS) and plain text for pasting into job portals.
(function () {
  const sheet = document.getElementById("resume");
  if (!sheet) return;
  const role = sheet.dataset.role;
  const KEY = `aipf:resume:${role}`;
  const original = sheet.innerHTML;
  const status = document.getElementById("resumeStatus");
  const store = {
    get() { try { return localStorage.getItem(KEY); } catch (e) { return null; } },
    set(v) { try { localStorage.setItem(KEY, v); } catch (e) { /* private mode */ } },
    del() { try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ } }
  };
  const say = msg => { if (status) { status.textContent = msg; clearTimeout(say.t); say.t = setTimeout(() => (status.textContent = ""), 2500); } };

  const saved = store.get();
  if (saved) { sheet.innerHTML = saved; say("Loaded your saved edits"); }

  // Live ATS keyword checklist
  const kwItems = [...document.querySelectorAll("[data-kw]")];
  const kwCount = document.getElementById("kwCount");
  function checkKeywords() {
    const text = sheet.innerText.toLowerCase();
    let found = 0;
    kwItems.forEach(li => {
      const ok = text.includes(li.dataset.kw.toLowerCase());
      li.classList.toggle("found", ok);
      li.querySelector(".kw-mark").textContent = ok ? "✓" : "✗";
      if (ok) found++;
    });
    if (kwCount) kwCount.textContent = `${found} / ${kwItems.length}`;
  }
  checkKeywords();

  // Editing
  const editBtn = document.querySelector('[data-act="edit"]');
  let saveTimer;
  editBtn.addEventListener("click", () => {
    const on = sheet.getAttribute("contenteditable") !== "true";
    sheet.setAttribute("contenteditable", on ? "true" : "false");
    sheet.classList.toggle("editing", on);
    editBtn.setAttribute("aria-pressed", on);
    editBtn.textContent = on ? "✓ Done editing" : "✏️ Edit resume";
    if (on) { sheet.focus(); say("Click any text to change it. Press Enter in a bullet to add a new one."); }
  });
  sheet.addEventListener("input", () => {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => { store.set(sheet.innerHTML); checkKeywords(); say("Saved in this browser"); }, 400);
  });
  // Paste as plain text, so formatting from other apps can't break the ATS-friendly layout.
  sheet.addEventListener("paste", e => {
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData("text/plain");
    document.execCommand("insertText", false, text);
  });

  const filename = ext => `${(document.querySelector(".rs-name") || {}).innerText || "resume"}`.trim().replace(/\s+/g, "-").toLowerCase() + `-${role}.${ext}`;
  const download = (content, type, name) => {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([content], { type }));
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 0);
  };

  document.querySelector('[data-act="word"]').addEventListener("click", () => {
    const clone = sheet.cloneNode(true);
    clone.removeAttribute("contenteditable");
    const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="utf-8"><title>Resume</title>
<style>
  @page { margin: 1.8cm 2cm; }
  body { font-family: Calibri, Carlito, Arial, sans-serif; font-size: 10.5pt; color: #111; line-height: 1.28; }
  .rs-head { text-align: center; }
  h2 { font-size: 16pt; margin: 0; }
  h3 { font-size: 11.5pt; text-transform: uppercase; letter-spacing: .4pt; border-bottom: 1px solid #111; margin: 10pt 0 4pt; padding-bottom: 1pt; }
  p { margin: 0 0 4pt; } ul { margin: 2pt 0 6pt 18pt; padding: 0; } li { margin: 0 0 2pt; }
  .rs-title { font-size: 12pt; font-weight: bold; } .rs-contact { font-size: 10pt; }
  .rs-entry-head { margin-top: 6pt; } .rs-dates { float: right; }
</style></head><body>${clone.innerHTML}</body></html>`;
    download("﻿" + html, "application/msword", filename("doc"));
    say("Word file downloaded. Open it in Word or Google Docs, then save as .docx");
  });

  document.querySelector('[data-act="pdf"]').addEventListener("click", () => window.print());

  document.querySelector('[data-act="text"]').addEventListener("click", () => {
    const text = sheet.innerText.replace(/\n{3,}/g, "\n\n");
    if (navigator.clipboard) navigator.clipboard.writeText(text).then(() => say("Copied as plain text"), () => download(text, "text/plain", filename("txt")));
    else download(text, "text/plain", filename("txt"));
  });

  document.querySelector('[data-act="reset"]').addEventListener("click", () => {
    if (!confirm("Reset to the original sample? Your edits will be lost.")) return;
    store.del();
    sheet.innerHTML = original;
    checkKeywords();
    say("Reset to the sample");
  });
})();
